   112  // head - Font Header
   113  // http://www.microsoft.com/typography/otspec/head.htm
   114
   115  namespace ots {
   116
   117  bool OpenTypeHEAD::Parse(const uint8_t *data, size_t length) {
   118    Buffer table(data, length);
   119
   120    uint32_t version = 0;
   121    if (!table.ReadU32(&version) ||
   122        !table.ReadU32(&this->revision)) {
   123      return Error("Failed to read table header");
   124    }
   125
   126    if (version >> 16 != 1) {
   127      return Error("Unsupported majorVersion: %d", version >> 16);
   128    }
   129
   130    // Skip the checksum adjustment
   131    if (!table.Skip(4)) {
   132      return Error("Failed to read checksum");
   133    }
   134
   135    uint32_t magic;
   136    if (!table.ReadU32(&magic) || magic != 0x5F0F3CF5) {
   137      return Error("Failed to read or incorrect magicNumber");
   138    }
   139
   140    if (!table.ReadU16(&this->flags)) {
   141      return Error("Failed to read flags");
   142    }
   143
   144    // We allow bits 0..4, 11..13
   145    this->flags &= 0x381f;
   146
   147    if (!table.ReadU16(&this->upem)) {
   148      return Error("Failed to read unitsPerEm");
   149    }
   150
   151    // upem must be in range
   152    if (this->upem < 16 ||
   153        this->upem > 16384) {
   154      return Error("unitsPerEm on in the range [16, 16384]: %d", this->upem);
   155    }
   156
   157    if (!table.ReadR64(&this->created) ||
   158        !table.ReadR64(&this->modified)) {
   159      return Error("Can't read font dates");
   160    }
   161
   162    if (!table.ReadS16(&this->xmin) ||
   163        !table.ReadS16(&this->ymin) ||
   164        !table.ReadS16(&this->xmax) ||
   165        !table.ReadS16(&this->ymax)) {
   166      return Error("Failed to read font bounding box");
   167    }
   168
   169    if (this->xmin > this->xmax) {
   170      return Error("Bad x dimension in the font bounding box (%d, %d)",
   171                    this->xmin, this->xmax);
   172    }
   173    if (this->ymin > this->ymax) {
   174      return Error("Bad y dimension in the font bounding box (%d, %d)",
   175                    this->ymin, this->ymax);
   176    }
   177
   178    if (!table.ReadU16(&this->mac_style)) {
   179      return Error("Failed to read macStyle");
   180    }
   181
   182    // We allow bits 0..6
   183    this->mac_style &= 0x7f;
   184
   185    if (!table.ReadU16(&this->min_ppem)) {
   186      return Error("Failed to read lowestRecPPEM");
   187    }
   188
   189    // We don't care about the font direction hint
   190    if (!table.Skip(2)) {
   191      return Error("Failed to read fontDirectionHint");
   192    }
   193
   194    if (!table.ReadS16(&this->index_to_loc_format)) {
   195      return Error("Failed to read indexToLocFormat");
   196    }
   197    if (this->index_to_loc_format < 0 ||
   198        this->index_to_loc_format > 1) {
   199      return Error("Bad indexToLocFormat %d", this->index_to_loc_format);
   200    }
   201
   202    int16_t glyph_data_format;
   203    if (!table.ReadS16(&glyph_data_format) ||
   204        glyph_data_format) {
   205      return Error("Failed to read or bad glyphDataFormat");
   206    }
   207
   208    return true;
   209  }
   210
   211  bool OpenTypeHEAD::Serialize(OTSStream *out) {
   212    if (!out->WriteU32(0x00010000) ||
   213        !out->WriteU32(this->revision) ||
   214        !out->WriteU32(0) ||  // check sum not filled in yet
   215        !out->WriteU32(0x5F0F3CF5) ||
   216        !out->WriteU16(this->flags) ||
   217        !out->WriteU16(this->upem) ||
   218        !out->WriteR64(this->created) ||
   219        !out->WriteR64(this->modified) ||
   220        !out->WriteS16(this->xmin) ||
   221        !out->WriteS16(this->ymin) ||
   222        !out->WriteS16(this->xmax) ||
   223        !out->WriteS16(this->ymax) ||
   224        !out->WriteU16(this->mac_style) ||
   225        !out->WriteU16(this->min_ppem) ||
   226        !out->WriteS16(2) ||
   227        !out->WriteS16(this->index_to_loc_format) ||
   228        !out->WriteS16(0)) {
   229      return Error("Failed to write table");
   230    }
   231
   232    return true;
   233  }
